{"charges": [{"claim": "When options.keepQueryParameters is an empty array, the function incorrectly removes all query parameters instead of preserving them.", "file": "index.js", "line": 231, "severity": "major", "witnessCode": "import test from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('keepQueryParameters empty array should keep query parameters', async t => {
  const url = 'https://example.com/path?foo=1&bar=2';
  const options = {
    keepQueryParameters: [],
    removeQueryParameters: [],
    sortQueryParameters: true,
  };
  const expected = 'https://example.com/path?bar=2&foo=1';
  const actual = normalizeUrl(url, options);
  assert.strictEqual(actual, expected);
});"}]}
